from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def get_linear_coord(x, y):
            if y == 0:
                return x
            elif x == side:
                return side + y
            elif y == side:
                return 2 * side + (side - x)
            elif x == 0:
                return 3 * side + (side - y)
            return 0  # Should not happen as points are on boundary

        # Sort points by their linear coordinate along the boundary
        sorted_points = sorted(points, key=lambda p: get_linear_coord(p[0], p[1]))

        def can_select(d: int) -> bool:
            count = 0
            last_x, last_y = -1, -1
            for x, y in sorted_points:
                if count == 0:
                    last_x, last_y = x, y
                    count = 1
                    continue
                dist = abs(x - last_x) + abs(y - last_y)
                if dist >= d:
                    last_x, last_y = x, y
                    count += 1
            return count >= k

        low = 0
        high = 2 * side
        ans = 0
        while low <= high:
            mid = (low + high) // 2
            if mid == 0:
                ans = max(ans, mid)
                low = mid + 1
                continue
            if can_select(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1
        return ans

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        if n == 0:
            return 0
        m = len(grid[0])
        if m == 0:
            return 0

        directions = [
            (1, 1),   # down-right
            (1, -1),  # down-left
            (-1, -1), # up-left
            (-1, 1)   # up-right
        ]

        # Map direction index to clockwise next direction index
        # Clockwise order: down-right (0) -> down-left (1) -> up-left (2) -> up-right (3) -> down-right (0)
        clockwise_next = [1, 2, 3, 0]

        max_len = 0

        for i in range(n):
            for j in range(m):
                if grid[i][j] != 1:
                    continue

                # Try each starting direction
                for start_dir_idx in range(4):
                    di, dj = directions[start_dir_idx]
                    r, c = i + di, j + dj
                    length = 1  # Start with the '1'

                    # Check the first step (must be 2)
                    if 0 <= r < n and 0 <= c < m and grid[r][c] == 2:
                        length += 1
                        # Continue in the same direction
                        while True:
                            r_next, c_next = r + di, c + dj
                            if 0 <= r_next < n and 0 <= c_next < m:
                                # Next expected value: 0, then 2, then 0, ...
                                # After the first 2, the pattern is 0, 2, 0, 2...
                                # So at step k (0-indexed after the first 2), expected is 0 if k is even, 2 if k is odd
                                # But we are in the loop after the first 2, so:
                                # Step 1 (first after 2): should be 0
                                # Step 2: should be 2
                                # etc.
                                # We can track the expected value by toggling
                                if grid[r_next][c_next] == 0:
                                    length += 1
                                    r, c = r_next, c_next
                                else:
                                    break
                            else:
                                break

                        # Now check for a clockwise turn
                        next_dir_idx = clockwise_next[start_dir_idx]
                        ndi, ndj = directions[next_dir_idx]
                        r_turn, c_turn = r + ndi, c + ndj
                        if 0 <= r_turn < n and 0 <= c_turn < m:
                            # After a turn, the sequence continues: the next value should be 2 (since we just finished a 0)
                            if grid[r_turn][c_turn] == 2:
                                length += 1
                                # Continue in the new direction
                                while True:
                                    r_next, c_next = r_turn + ndi, c_turn + ndj
                                    if 0 <= r_next < n and 0 <= c_next < m:
                                        # After the first 2 after turn, the pattern is 0, 2, 0, 2...
                                        # So next should be 0
                                        if grid[r_next][c_next] == 0:
                                            length += 1
                                            r_turn, c_turn = r_next, c_next
                                        else:
                                            break
                                    else:
                                        break
                            else:
                                # Cannot continue after turn
                                pass
                        else:
                            # Cannot turn
                            pass

                    max_len = max(max_len, length)

        return max_len

import sys
import bisect

# Increase recursion depth just in case, though we are not using recursion
sys.setrecursionlimit(200000)

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        Q = int(next(iterator))

        A = []
        for _ in range(N):
            A.append(int(next(iterator)))

        queries = []
        for i in range(Q):
            R = int(next(iterator))
            X = int(next(iterator))
            queries.append((R, X, i))
    except StopIteration:
        return

    # Coordinate compression for values in A
    distinct_vals = sorted(list(set(A)))
    val_to_rank = {val: i+1 for i, val in enumerate(distinct_vals)}
    num_distinct = len(distinct_vals)

    # Fenwick tree (Binary Indexed Tree) for range maximum query
    tree = [0] * (num_distinct + 1)

    def update(idx, value):
        while idx <= num_distinct:
            if value > tree[idx]:
                tree[idx] = value
            idx += idx & (-idx)

    def query(idx):
        res = 0
        while idx > 0:
            if tree[idx] > res:
                res = tree[idx]
            idx -= idx & (-idx)
        return res

    # Sort queries by R_i
    queries.sort(key=lambda x: x[0])

    results = [0] * Q
    current_R = 0

    for R, X, original_index in queries:
        # Add elements from current_R to R-1 (since R is 1-indexed, we go up to index R-1)
        while current_R < R:
            val = A[current_R]
            rank = val_to_rank[val]

            # Query the maximum LIS length for values with rank < rank (i.e., strictly less than val)
            if rank > 1:
                prev_max = query(rank - 1)
            else:
                prev_max = 0

            new_len = prev_max + 1
            update(rank, new_len)

            current_R += 1

        # For the query, find the largest rank in distinct_vals that is <= X.
        pos = bisect.bisect_right(distinct_vals, X)

        if pos == 0:
            results[original_index] = 0
        else:
            results[original_index] = query(pos)

    for res in results:
        print(res)

if __name__ == '__main__':
    solve()

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def check(k):
            if k >= n:
                return True
            ops_needed = 0
            i = 0
            while i < n:
                j = i
                while j < n and s[j] == s[i]:
                    j += 1
                length = j - i
                if length > k:
                    ops_needed += (length - 1) // k
                i = j
                if ops_needed > numOps:
                    return False
            return ops_needed <= numOps

        low, high = 1, n
        ans = n
        while low <= high:
            mid = (low + high) // 2
            if check(mid):
                ans = mid
                high = mid - 1
            else:
                low = mid + 1
        return ans
